mapper.select:
select bai.id, bai.account_type as accountType, bai.ba_digital_rmb_company_id as companyID, case bai.account_type when '01' then bai.Ba_Company_Name when '02' then sc2.C_Name end as companyName, case bai.account_type when '01' then bai.ba_bank_name when '02' then bai.ba_digital_rmb_bank_name end as bankName, case bai.account_type when '01' then bai.ba_bank_account when '02' then bai.ba_digital_rmb_account end as bankAccount, bai.p_id as pId, pp.P_Name as pName, pp.P_Name as projectName, bai.state, bai.create_time as createTime, bai.create_uid as createUid, bai.create_uname as createUname, bai.state_time as stateTime from Bank_Account_Info bai left join Pre_Project pp on bai.p_id = pp.P_ID left join SYS_company sc on bai.ba_company_id = sc.c_ID left join SYS_Company sc2 on bai.ba_digital_rmb_company_id = sc2.C_ID
bai.state !=3
and bai.p_id = #{params.pID}
and likePname(#{params.pName},pp.P_Id)=true
and likeCname(#{params.companyName},sc2.C_Id)=true
and likeCname(#{params.companyName},sc.C_Id)=true
and pp.P_Name like concat('%',#{params.pName},'%')
and sc2.C_Name like concat('%',#{params.companyName},'%')
and sc.C_Name like concat('%',#{params.companyName},'%')
and bai.account_type = #{params.accountType}
and bai.ba_company_id = #{params.companyID}
and bai.ba_digital_rmb_company_id = #{params.companyID}

select bai.id, bai.account_type as accountType, bai.ba_digital_rmb_company_id as companyID, case bai.account_type when '01' then bai.Ba_Company_Name when '02' then sc2.C_Name end as companyName, case bai.account_type when '01' then bai.ba_bank_name when '02' then bai.ba_digital_rmb_bank_name end as bankName, case bai.account_type when '01' then bai.ba_bank_account when '02' then bai.ba_digital_rmb_account end as bankAccount, bai.p_id as pId, pp.P_Name as pName, pp.P_Name as projectName, bai.state, bai.create_time as createTime, bai.create_uid as createUid, bai.create_uname as createUname, bai.state_time as stateTime from Bank_Account_Info bai left join Pre_Project pp on bai.p_id = pp.P_ID left join SYS_Department sc on bai.ba_company_id = sc.D_ID left join SYS_Company sc2 on bai.ba_digital_rmb_company_id = sc2.C_ID
bai.state !=3
and bai.id = #{params.id}
